1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
26	import {log} from '../shared/logger.js';
27	
28	const DEFAULT_MAX_TOOL_ROUNDS = 5;
29	
30	function ensureError(value: unknown): Error {
31	  if (value instanceof Error) return value;
32	  if (typeof value === 'string') return new Error(value);
33	  return new Error(JSON.stringify(value));
34	}
35	
36	export interface OrchestratorHooks {
37	  beforeSession?: (session: ChatSession) => Promise<void>;
38	  afterSession?: (session: ChatSession) => Promise<void>;
39	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
40	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
41	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
42	  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: UsageMetadata) => Promise<void>;
43	  onError?: (session: ChatSession, error: Error) => Promise<void>;
44	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
45	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
46	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
47	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
48	}
49	
50	export interface ToolBudgetInfo {
51	  maxToolRounds: number;
52	  requestedTools: string[];
53	}
54	
55	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
56	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
57	
58	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
59	
60	export interface ChatOrchestrator {
61	  processMessage(session: ChatSession): Promise<string>;
62	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
63	}
64	
65	export interface ChatOrchestratorOptions {
66	  maxToolRounds?: number;
67	  contextConfig?: Partial<ContextConfig>;
68	  promptBuilderOptions?: PromptBuilderOptions;
69	  hooks?: OrchestratorHooks;
70	  sessionStore?: SessionStore;
71	}
72	
73	interface ToolExecutionResult {
74	  clientMessages: OutgoingMessage[];
75	  suppressOutput: boolean;
76	}
77	export function createChatOrchestrator(
78	  provider: AIProvider,
79	  promptBuilder: PromptBuilder,
80	  toolRegistry?: ToolRegistry,
81	  options?: ChatOrchestratorOptions
82	): ChatOrchestrator {
83	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
84	  const contextConfig = createContextConfig(options?.contextConfig);
85	  const toolInstructions = toolRegistry?.getPromptInstructions();
86	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
87	  const tools = toolRegistry?.getDefinitions();
88	  const hooks = options?.hooks;
89	  const sessionStore = options?.sessionStore;
90	
91	  return {
92	    async processMessage(session: ChatSession): Promise<string> {
93	      return collectText(this.processMessageStream(session));
94	    },
95	
96	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
97	      try {
98	        if (hooks?.beforeSession) await hooks.beforeSession(session);
99	
100	        let userMessage = lastUserContent(session);
101	
102	        if (hooks?.beforeUserInput) {
103	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
104	        }
105	
106	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
107	
108	        const systemPrompt = hooks?.beforeModelResponse
109	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
110	          : baseSystemPrompt;
111	
112	        const messages: Message[] = toMessages(session.entries, contextConfig);
113	        let totalUsage: UsageMetadata | undefined;
114	        let responseText = '';
115	
116	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
117	        for (let round = 0; ; round++) {
118	          log.info('orchestrator', 'starting round', {round});
119	          const pendingToolCalls: ToolCall[] = [];
120	
121	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
122	          responseText += outcome.text;
123	          totalUsage = accumulateUsage(totalUsage, outcome.usage);
124	
125	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
126	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
127	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
128	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
129	            break;
130	          }
131	
132	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
133	          const {clientMessages, suppressOutput} = await executeToolCalls(
134	            pendingToolCalls,
135	            messages,
136	            session,
137	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
138	          );
139	          log.info('orchestrator', 'tool execution complete', {
140	            clientMessageCount: clientMessages.length,
141	            clientMessageTypes: clientMessages.map(m => m.type),
142	            suppressOutput,
143	          });
144	
145	          if (clientMessages.length > 0) {
146	            yield {type: 'tool_result' as const, clientMessages};
147	          }
148	
149	          if (suppressOutput) {
150	            yield {type: 'suppress_output' as const};
151	          }
152	        }
153	
154	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
155	      } catch (error) {
156	        if (hooks?.onError) {
157	          await hooks.onError(session, ensureError(error));
158	        }
159	        throw error;
160	      } finally {
161	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
162	        commitStreamingEntries(session);
163	        try {
164	          if (hooks?.afterSession) await hooks.afterSession(session);
165	        } finally {
166	          await saveSession(sessionStore, session);
167	        }
168	      }
169	    },
170	  };
171	}
172	
173	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
174	function normalizeToolRounds(value: number | undefined): number {
175	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
176	  return Math.max(0, Math.floor(value));
177	}
178	
179	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
180	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
181	  if (round < maxToolRounds) return false;
182	  log.warn('orchestrator', 'tool budget exhausted', {
183	    maxToolRounds,
184	    requestedTools: pendingToolCalls.map(tc => tc.name),
185	  });
186	  return true;
187	}
188	
189	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
190	async function* closeExhaustedTurn(
191	  session: ChatSession,
192	  budget: ToolBudgetInfo,
193	  hook?: OnToolBudgetExhausted
194	): AsyncGenerator<MessageChunk, string> {
195	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
196	  if (sentence !== '') yield {type: 'text', text: sentence};
197	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
198	  return sentence;
199	}
200	
201	interface RoundOutcome {
202	  stopReason: string;
203	  text: string;
204	  usage?: UsageMetadata;
205	}
206	
207	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
208	async function* streamRound(
209	  provider: AIProvider,
210	  request: SendMessageParams,
211	  pendingToolCalls: ToolCall[]
212	): AsyncGenerator<MessageChunk, RoundOutcome> {
213	  let stopReason = '';
214	  let text = '';
215	  let usage: UsageMetadata | undefined;
216	
217	  for await (const chunk of provider.sendMessage(request)) {
218	    yield chunk;
219	    collectToolCalls(chunk, pendingToolCalls);
220	    stopReason = extractStopReason(chunk) ?? stopReason;
221	    usage = extractUsage(chunk) ?? usage;
222	    if (chunk.type === 'text') text += chunk.text;
223	  }
224	
225	  return {stopReason, text, usage};
226	}
227	
228	// A changed message is also written back to the session's last user entry.
229	async function rewriteUserMessage(
230	  session: ChatSession,
231	  userMessage: string,
232	  hook: (session: ChatSession, userMessage: string) => Promise<string>
233	): Promise<string> {
234	  const modified = await hook(session, userMessage);
235	  if (modified === userMessage) return userMessage;
236	
237	  updateLastUserContent(session, modified);
238	  return modified;
239	}
240	
241	function lastUserContent(session: ChatSession): string {
242	  for (let i = session.entries.length - 1; i >= 0; i--) {
243	    const entry = session.entries[i];
244	    if (entry.role === 'user') return entry.content;
245	  }
246	  return '';
247	}
248	
249	function updateLastUserContent(session: ChatSession, content: string): void {
250	  for (let i = session.entries.length - 1; i >= 0; i--) {
251	    const entry = session.entries[i];
252	    if (entry.role === 'user') {
253	      entry.content = content;
254	      return;
255	    }
256	  }
257	}
258	
259	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
260	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
261	  const context: ToolContext = {
262	    userId: session.userId,
263	    sessionId: session.sessionId,
264	    workspaceId: session.workspaceId,
265	    authHeaders: session.authHeaders,
266	  };
267	
268	  return async (tc: ToolCall): Promise<ToolResponse> => {
269	    const declined =
270	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
271	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
272	  };
273	}
274	
275	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
276	async function consultPolicy(
277	  policy: BeforeToolCall,
278	  session: ChatSession,
279	  tc: ToolCall
280	): Promise<ToolResponse | undefined> {
281	  try {
282	    return await policy(session, tc);
283	  } catch (error) {
284	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
285	      tool: tc.name,
286	      errorType: error instanceof Error ? error.name : typeof error,
287	    });
288	    return {result: `The ${tc.name} call was declined and not performed.`};
289	  }
290	}
291	
292	async function executeToolCalls(
293	  pendingToolCalls: ToolCall[],
294	  messages: Message[],
295	  session: ChatSession,
296	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
297	): Promise<ToolExecutionResult> {
298	  messages.push(buildToolCallMessages(pendingToolCalls));
299	
300	  const responses = await Promise.all(
301	    pendingToolCalls.map(async tc => {
302	      const response = await runToolCall(tc);
303	      return {tc, response};
304	    })
305	  );
306	
307	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
308	    type: 'tool_result' as const,
309	    toolUseId: tc.id,
310	    content: response.result,
311	  }));
312	  messages.push({role: 'user', content: toolResults});
313	
314	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
315	
316	  return {
317	    clientMessages: assignEntryIndices(rawClientMessages, session),
318	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
319	  };
320	}
321	
322	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
323	  return clientMessages.map(msg => {
324	    if (msg.type !== 'entry_upsert') return msg;
325	    const index = appendEntry(session, msg.entry);
326	    return {...msg, index};
327	  });
328	}
329	
330	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
331	function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
332	  if (!acc) return next;
333	  if (!next) return acc;
334	  return {
335	    inputTokens: acc.inputTokens + next.inputTokens,
336	    outputTokens: acc.outputTokens + next.outputTokens,
337	    totalTokens: acc.totalTokens + next.totalTokens,
338	  };
339	}
340	
341	// A store outage is not a reason to fail the turn the customer already received.
342	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
343	  if (!store?.save) return;
344	
345	  try {
346	    await store.save(session);
347	  } catch (error) {
348	    const message = error instanceof Error ? error.message : String(error);
349	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
350	  }
351	}
